package com.bank.comp.model;

import java.math.BigDecimal;

// Holds the inputs behind a salary expectation — never a bare, unexplained number.
public class CompExpectation {
    private final BigDecimal marketMedianBase;
    private final BigDecimal levelFactor;
    private final BigDecimal locationFactor;
    private final BigDecimal bonus;
    private final BigDecimal equityBenefits;

    public CompExpectation(BigDecimal marketMedianBase, BigDecimal levelFactor,
                           BigDecimal locationFactor, BigDecimal bonus,
                           BigDecimal equityBenefits) {
        this.marketMedianBase = marketMedianBase;
        this.levelFactor = levelFactor;
        this.locationFactor = locationFactor;
        this.bonus = bonus;
        this.equityBenefits = equityBenefits;
    }

    public BigDecimal getMarketMedianBase() { return marketMedianBase; }
    public BigDecimal getLevelFactor() { return levelFactor; }
    public BigDecimal getLocationFactor() { return locationFactor; }
    public BigDecimal getBonus() { return bonus; }
    public BigDecimal getEquityBenefits() { return equityBenefits; }
}
