package com.bank.comp.service;

import com.bank.comp.model.CompExpectation;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.*;

// Derives a defensible base range and total package from the research inputs.
public class CompCalculator {
    private final Logger log;

    public CompCalculator(Logger log) { this.log = log; }

    public void explain(CompExpectation e) {
        // Expected base = median × level × location (all BigDecimal, no float).
        BigDecimal expectedBase = e.getMarketMedianBase()
            .multiply(e.getLevelFactor())
            .multiply(e.getLocationFactor())
            .setScale(0, RoundingMode.HALF_UP);

        // Build a sensible range: ±8% around the derived base.
        BigDecimal low = expectedBase.multiply(new BigDecimal("0.92"))
            .setScale(0, RoundingMode.HALF_UP);
        BigDecimal high = expectedBase.multiply(new BigDecimal("1.08"))
            .setScale(0, RoundingMode.HALF_UP);

        // Total package optimizes the whole expression, not just base.
        BigDecimal totalPackage = expectedBase.add(e.getBonus()).add(e.getEquityBenefits());

        log.info(() -> "Inputs: median=" + e.getMarketMedianBase()
            + " level=" + e.getLevelFactor() + " location=" + e.getLocationFactor());
        log.info(() -> "Derived base range: " + low + " to " + high);
        log.info(() -> "Total package (base+bonus+equity): " + totalPackage);
        log.info(() -> "Flexible on mix if the overall package and growth are strong.");
    }
}
